## 3️⃣ Embed a Track (or Playlist) with the Widget

You can embed any public track using its URL or ID. The widget gives you full playback control (play, pause, seek, volume, etc.).

```html
<!-- Container for the widget -->
<div id="sc-player"></div>

<script>
  // Example track URL – replace with any track you want
  const trackUrl = 'https://soundcloud.com/forss/flickermood';

  // Create the widget iframe
  const iframe = document.createElement('iframe');
  iframe.setAttribute('width', '100%');
  iframe.setAttribute('height', '166');
  iframe.setAttribute('scrolling', 'no');
  iframe.setAttribute('frameborder', 'no');
  iframe.setAttribute('allow', 'autoplay');
  iframe.src = `https://w.soundcloud.com/player/?url=${encodeURIComponent(trackUrl)}&auto_play=false&hide_related=false&show_comments=true&show_user=true&show_reposts=false&visual=true`;

  // Append to the container
  document.getElementById('sc-player').appendChild(iframe);

  // Get the widget API object
  const widget = SC.Widget(iframe);

  // Example: Play the track when the widget is ready
  widget.bind(SC.Widget.Events.READY, function() {
    console.log('SoundCloud widget ready');
    // widget.play(); // Uncomment to auto‑play
  });

  // Optional: Add custom controls
  function play()  { widget.play(); }
  function pause() { widget.pause(); }
  function seek(seconds) { widget.seekTo(seconds * 1000); } // widget uses ms
</script>
```

### Custom Controls (HTML)

